<template><form class="scr-form" @submit.prevent="save"><label>{{ t('garage.name') }}<input v-model="draft.name" maxlength="128" /></label><label>{{ t('garage.rating') }}<input v-model.number="draft.rating" type="number" min="0" max="5" /></label><label>{{ t('garage.collection') }}<input v-model="draft.collection" maxlength="128" /></label><label>{{ t('garage.tags') }}<input v-model="draft.tags" maxlength="512" /></label><label>{{ t('garage.notes') }}<textarea v-model="draft.notes" maxlength="4096"></textarea></label><button type="submit">{{ t('common.save') }}</button></form></template>
<script setup>
import { reactive, watch } from "vue"; import { useStores } from "../../stores"
const props = defineProps({ entry: { type: Object, required: true } }); const stores = useStores(); const { t } = stores.i18n; const draft = reactive({ name: "", rating: 0, collection: "", tags: "", notes: "" })
watch(() => props.entry, value => Object.assign(draft, { name: value?.name || "", rating: value?.rating || 0, collection: value?.collection || "", tags: (value?.tags || []).join(", "), notes: value?.notes || "" }), { immediate: true })
function save() { const id = props.entry.id; const tags = [...new Set(draft.tags.split(",").map(v => v.trim()).filter(Boolean))].slice(0, 16); if (draft.name.trim() && draft.name.trim() !== props.entry.name) stores.command.send("renameVehicleDNA", [id, draft.name.trim()]); stores.command.send("setVehicleDNARating", [id, Number(draft.rating) || 0]); stores.command.send("setVehicleDNACollection", [id, draft.collection]); stores.command.send("setVehicleDNATags", [id, tags]); stores.command.send("setVehicleDNANotes", [id, draft.notes]) }
</script>
